INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('凉拌/口水鸡.md#step-1',88,1,NULL,'口水鸡料配制（5 份）：125g 口水鸡底料、125g 拌菜红油、15g 蒜末、8g 藤椒油、50g 纯净水、20g 熟白芝麻；','凉拌/口水鸡.md#step-1',NULL,NULL,NULL,NULL);
