INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('汤/菌菇鸡汤.md#step-1',105,1,NULL,'老母鸡鸡块用流水清洗干净。锅中放入足量水，加入鸡块，水烧开立即关火。鸡块捞出后冷水冲洗干净留待后续使用。','汤/菌菇鸡汤.md#step-1',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('汤/菌菇鸡汤.md#step-2',105,2,NULL,'取特色鸡汤盅，放入焯水后的老母鸡鸡块40g、菌菇混合包20g、姜片1g、菌菇鸡汤汤底320g，盖上鸡汤盅盖，再放入上汽蒸柜中蒸制90分钟，即可完成。','汤/菌菇鸡汤.md#step-2',5400,NULL,NULL,NULL);
