INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/阳春面.md#step-1',132,1,NULL,'汤底调配：4200g水烧开后加入24g盐、60g鸡精、15g老抽、6g十三香、25g浓缩鸡汁，烧开后关火留待后续使用；','主食/阳春面.md#step-1',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/阳春面.md#step-2',132,2,NULL,'组合：取15g青蒜花、15g熟猪油、1g白胡椒粉置于面碗中，舀入350g底汤；再将110g挂面放入面篓中煮制4分钟，捞起沥水后放入碗中即可完成。','主食/阳春面.md#step-2',240,NULL,NULL,NULL);
