INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/雪菜肉丝面.md#step-1',135,1,NULL,'面条汤底制做（5 份）：将 250g 西红柿片用 100g 大豆油炒制表皮收缩；加入 2800g 水、140g 汤料、100g 千张丝、400g 雪菜肉丝、75g 炒菜基料大火烧开后煮 2 分钟，留待后续使用；','主食/雪菜肉丝面.md#step-1',120,NULL,'大火',NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/雪菜肉丝面.md#step-2',135,2,NULL,'将 275g 手擀面在沸水中煮 3 分钟；','主食/雪菜肉丝面.md#step-2',180,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/雪菜肉丝面.md#step-3',135,3,NULL,'舀取 650g 面条汤底于面碗中，放入煮好的面条，撒 3g 葱花即可完成。','主食/雪菜肉丝面.md#step-3',NULL,NULL,NULL,NULL);
