INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/五彩鸡丝拌面.md#step-1',242,1,NULL,'将大麦若叶拉面在煮面篓中煮约30 秒，捞出用直饮水冲凉，沥干水分后放入份盒中。按照每份面（煮熟后约220g）加入8g 菜籽油的比例，搅拌均匀；','主食/五彩鸡丝拌面.md#step-1',30,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/五彩鸡丝拌面.md#step-2',242,2,NULL,'在面碗中，先放入220g 搅拌均匀的含油面条，然后均匀放入40g 自制拌面汁，最后依次摆入30g 蛋皮丝（需要在煮面篓中烫制10 秒后沥干水分）、30g 黄瓜丝、30g 焯水后绿豆芽、30g 焯水后胡萝卜丝、30g 老母鸡鸡丝，即可完成。','主食/五彩鸡丝拌面.md#step-2',10,NULL,NULL,NULL);
