INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/大大大块牛腩面.md#step-1',243,1,NULL,'牛腩烧制：①锅中加入120g 菜籽油烧至180℃，加入25g 姜片炒香； ②加入1000g 焯过水的牛腩、25g 大葱段充分煸炒，加入12g 老抽上色； ③加入150g 清油火锅底料炒香，加1300g 水烧开； ④加入4g 盐、3g 白砂糖后倒入高压锅小火压18 分钟焖5 分钟； ⑤开盖捞出姜葱，加入15g 藤椒油，搅拌均匀留待后续使用。','主食/大大大块牛腩面.md#step-1',1080,'180℃','小火',NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/大大大块牛腩面.md#step-2',243,2,NULL,'10 份底汤调制：2400g 开水中加入120g 汤料，搅拌均匀留待后续使用；','主食/大大大块牛腩面.md#step-2',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/大大大块牛腩面.md#step-3',243,3,NULL,'将130g 鲜面和25g 青菜在沸水中煮2 分钟；','主食/大大大块牛腩面.md#step-3',120,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/大大大块牛腩面.md#step-4',243,4,NULL,'面碗中加入20g 牛肉面汤底料、20g 红油、5g 蒜蓉、5g熟猪油、250g 底汤，放入煮好的面条；','主食/大大大块牛腩面.md#step-4',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/大大大块牛腩面.md#step-5',243,5,NULL,'将80g 牛腩和25g 青菜摆放在面条上，加入20g 牛腩汤汁，撒入5g 香菜、5g 葱花即可完成。','主食/大大大块牛腩面.md#step-5',NULL,NULL,NULL,NULL);
