INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/大排面.md#step-1',244,1,NULL,'大排卤制： ①在不锈钢桶中放入5000g 水、500g 卤料和500g 卤油，大火烧开后，捞出料渣； ②解冻后的油炸大排放入卤汤中，大火烧开后转小火卤制10 分钟，关火焖5 分钟。','主食/大排面.md#step-1',600,NULL,'大火',NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/大排面.md#step-2',244,2,NULL,'10 份面条汤底配制：不锈钢桶中加入3500g 水烧开，加入150g 熟猪油、30g 盐、10g 老抽烧开，保温留待后续使用；','主食/大排面.md#step-2',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/大排面.md#step-3',244,3,NULL,'将110g 手工挂面和3 颗青菜在沸水中煮3 分钟；','主食/大排面.md#step-3',180,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/大排面.md#step-4',244,4,NULL,'舀取350g 面条汤底放入面碗中，再放入煮好的面条；','主食/大排面.md#step-4',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/大排面.md#step-5',244,5,NULL,'将1 块大排、3 颗青菜、半个卤蛋放于面条上，加入30g卤汤，撒入5g 蒜花即可完成。','主食/大排面.md#step-5',NULL,NULL,NULL,NULL);
