INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/大盘肥肠鸡手工面.md#step-1',245,1,NULL,'鸡块制作：','主食/大盘肥肠鸡手工面.md#step-1',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/大盘肥肠鸡手工面.md#step-2',245,2,NULL,'加入350g 菜籽油、200g 猪油、清洗好沥干水分的3200g鸡块，煸炒至表皮微黄；','主食/大盘肥肠鸡手工面.md#step-2',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/大盘肥肠鸡手工面.md#step-3',245,3,NULL,'加入50g 葱、140g 姜、200g 蒜，炒出香味；','主食/大盘肥肠鸡手工面.md#step-3',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/大盘肥肠鸡手工面.md#step-4',245,4,NULL,'加入800g 肥肠鸡酱料，翻炒均匀；','主食/大盘肥肠鸡手工面.md#step-4',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/大盘肥肠鸡手工面.md#step-5',245,5,NULL,'加入3000g 水、40g 盐，煮制2 分钟即可倒出，鸡块和汤留待后续使用。','主食/大盘肥肠鸡手工面.md#step-5',120,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/大盘肥肠鸡手工面.md#step-6',245,6,NULL,'面片制作：','主食/大盘肥肠鸡手工面.md#step-6',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/大盘肥肠鸡手工面.md#step-7',245,7,NULL,'解冻完全的每个面胚扯成30-35cm 长的面片；','主食/大盘肥肠鸡手工面.md#step-7',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/大盘肥肠鸡手工面.md#step-8',245,8,NULL,'放入沸水中，煮制2 分钟，放入餐具中；','主食/大盘肥肠鸡手工面.md#step-8',120,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/大盘肥肠鸡手工面.md#step-9',245,9,NULL,'锅里放入450g 炒好的鸡块、70g 焯水的芋艿、40g 肥肠，烧开煮3 分钟；','主食/大盘肥肠鸡手工面.md#step-9',180,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/大盘肥肠鸡手工面.md#step-10',245,10,NULL,'再加入8g 线椒、5g 鲜红小米辣、10g 芝麻香油、5g 花椒油，继续煮制1 分钟，关火倒入餐具中；','主食/大盘肥肠鸡手工面.md#step-10',60,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/大盘肥肠鸡手工面.md#step-11',245,11,NULL,'20g 大豆油烧热，加入2g 干青花椒、5g 干红辣椒段，炸出香味后均匀淋到菜上；','主食/大盘肥肠鸡手工面.md#step-11',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/大盘肥肠鸡手工面.md#step-12',245,12,NULL,'最后点缀5g 白芝麻、5g 香菜段即可完成。','主食/大盘肥肠鸡手工面.md#step-12',NULL,NULL,NULL,NULL);
