INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/泡椒鸡杂面.md#step-1',247,1,NULL,'起锅烧油，依次爆香蒜姜、泡椒酱、泡红椒，再加入鸡肝、鸡肫、调味料，加水烧开后转中火收浓汤汁，最后下香葱翻匀出锅；','主食/泡椒鸡杂面.md#step-1',NULL,NULL,'中火',NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/泡椒鸡杂面.md#step-2',247,2,NULL,'水烧开，将1 包手擀面放入面篓中并用筷子搅散，煮制约2 分钟；同时加入青菜，烫制20 秒；','主食/泡椒鸡杂面.md#step-2',140,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/泡椒鸡杂面.md#step-3',247,3,NULL,'面碗中放入250g 老鸡汤、100g 泡椒鸡杂（汤汁）、煮好的面条，再加入120g 泡椒鸡杂（固形物）、20g 青菜、半个茶叶蛋，即可完成。','主食/泡椒鸡杂面.md#step-3',NULL,NULL,NULL,NULL);
