INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/浓香整块鸡汤面.md#step-1',248,1,NULL,'10 份汤底调制：1000g 开水中加入50g 汤料，搅拌均匀留待后续使用；','主食/浓香整块鸡汤面.md#step-1',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/浓香整块鸡汤面.md#step-2',248,2,NULL,'老鸡汤熬制： ①每只鸡用2g 盐均匀揉搓鸡表皮，冷藏20 分钟； ②每500g 老母鸡，加入16g 盐、60g 鸡油、2500g 水，烧开后炖制60 分钟，留待后续使用。','主食/浓香整块鸡汤面.md#step-2',1200,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/浓香整块鸡汤面.md#step-3',248,3,NULL,'鸡块制作： ①每500g 鸡用5g 盐、3g 鸡精、4g 葱段、2g 姜片腌制20 分钟； ②腌制好的小母鸡放入蒸柜中蒸制25 分钟； ③将蒸制好的鸡分切为四份，留待后续使用。','主食/浓香整块鸡汤面.md#step-3',1200,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/浓香整块鸡汤面.md#step-4',248,4,NULL,'将130g 鲜面、1 份鸡块、25g 青菜在沸水中煮2 分钟；','主食/浓香整块鸡汤面.md#step-4',120,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/浓香整块鸡汤面.md#step-5',248,5,NULL,'舀取200g 老鸡汤、100g 汤底于面碗中，放入煮好的面条和配菜，撒上5g 葱花即可完成。','主食/浓香整块鸡汤面.md#step-5',NULL,NULL,NULL,NULL);
