INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/炸鸡腿时蔬面.md#step-3',249,3,NULL,'取餐厅炸制后的鸡腿1 个、烫制后的西兰花2 颗（30g）、熟玉米1 块（40-45g）、熟南瓜1 块（25-30g）均匀摆放在餐具上，摆盘即可完成。','主食/炸鸡腿时蔬面.md#step-3',NULL,NULL,NULL,NULL);
