INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/笋子鸡丁盖饭（包菜版）.md#step-1',252,1,NULL,'笋子鸡丁炒制：(1) 180g大豆油烧至180℃、加入700g鸡丁炒熟；(2) 加入8g老抽、5g鸡精、2g盐，将鸡丁炒制上色；(3) 加入120g剁椒酱、300g焯水罗汉笋块，一起炒香；(4) 加入36g蒜花翻炒均匀，留待后续使用；','主食/笋子鸡丁盖饭（包菜版）.md#step-1',NULL,'180℃',NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/笋子鸡丁盖饭（包菜版）.md#step-2',252,2,NULL,'包菜烫制：取70g包菜，在沸水中烫1分钟，留待后续使用；','主食/笋子鸡丁盖饭（包菜版）.md#step-2',60,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/笋子鸡丁盖饭（包菜版）.md#step-3',252,3,NULL,'餐盒中放入300g米饭，将170g笋子鸡丁、70g包菜、半个卤蛋放在米饭上，包菜上淋入10g豉油汁即可完成。','主食/笋子鸡丁盖饭（包菜版）.md#step-3',NULL,NULL,NULL,NULL);
