INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/老母鸡汤面.md#step-2',257,2,NULL,'将鲜Q 面、青菜放入面篓，煮熟；','主食/老母鸡汤面.md#step-2',NULL,NULL,NULL,NULL);
