INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/老鸡扬米面.md#step-2',258,2,NULL,'每500g 老母鸡，加入16g 盐、60g 鸡油、2500g 水，烧开后炖制60 分钟；','主食/老鸡扬米面.md#step-2',3600,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/老鸡扬米面.md#step-3',258,3,NULL,'扬米面在温水浸泡8 小时，留待后续使用；','主食/老鸡扬米面.md#step-3',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/老鸡扬米面.md#step-4',258,4,NULL,'面碗中舀取400g 老鸡汤，留待后续使用；','主食/老鸡扬米面.md#step-4',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/老鸡扬米面.md#step-5',258,5,NULL,'将65g 鸡块、260g 扬米面、3 颗青菜、20g 蛋皮在沸水中煮15 秒，捞出，放入面碗中，撒上3g 葱花即可完成。','主食/老鸡扬米面.md#step-5',15,NULL,NULL,NULL);
