INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/西红柿炒鸡蛋盖饭.md#step-1',260,1,NULL,'西红柿炒鸡蛋炒制：加入200g大豆油、575g鸡蛋液，炒成蛋片，出锅留待后续使用；再加入50g大豆油、1800g西红柿块、8g盐、8g鸡精，大火翻炒；再加入鸡蛋片、24g水淀粉，翻炒均匀。','主食/西红柿炒鸡蛋盖饭.md#step-1',NULL,NULL,'大火',NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/西红柿炒鸡蛋盖饭.md#step-2',260,2,NULL,'卤鸡腿卤制：在不锈钢桶中放入5000g水、500g卤料和500g卤油，大火烧开后，捞出料渣，留待后续使用；解冻后的卤鸡腿放入卤汤中，大火烧开后转小火卤5分钟，关火焖5分钟。','主食/西红柿炒鸡蛋盖饭.md#step-2',300,NULL,'大火',NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/西红柿炒鸡蛋盖饭.md#step-3',260,3,NULL,'盖饭即可完成：餐盒中放入300g米饭，将1份西红柿炒鸡蛋、1个卤鸡腿放在米饭上，鸡腿上淋入20g卤汤，即可完成。','主食/西红柿炒鸡蛋盖饭.md#step-3',NULL,NULL,NULL,NULL);
