INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/香菇鸡汤面.md#step-1',261,1,NULL,'每只鸡用2g 盐均匀揉搓鸡表皮，冷藏20 分钟；','主食/香菇鸡汤面.md#step-1',1200,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/香菇鸡汤面.md#step-2',261,2,NULL,'每500g 老母鸡，加入16g 盐、60g 鸡油、2500g 水，烧开后炖制60 分钟；','主食/香菇鸡汤面.md#step-2',3600,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/香菇鸡汤面.md#step-3',261,3,NULL,'将110g 挂面在沸水中煮4 分钟；','主食/香菇鸡汤面.md#step-3',240,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/香菇鸡汤面.md#step-4',261,4,NULL,'取65g 老母鸡块、1 个香菇、3 颗青菜和20g 蛋皮在沸水中烫30 秒；','主食/香菇鸡汤面.md#step-4',30,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/香菇鸡汤面.md#step-5',261,5,NULL,'舀取500g 的老鸡汤于面碗中，放入煮好的面条和配菜。','主食/香菇鸡汤面.md#step-5',NULL,NULL,NULL,NULL);
