INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/香辣牛肉面.md#step-1',262,1,NULL,'汤底调制：将150g 牛肉面汤料、20g 姜片、10g 香葱、5000g水，烧开后煮20 分钟，捞渣留待后续使用；','主食/香辣牛肉面.md#step-1',1200,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/香辣牛肉面.md#step-2',262,2,NULL,'香辣牛肉大火烧开，转小火焖煮5 分钟；','主食/香辣牛肉面.md#step-2',300,NULL,'大火',NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/香辣牛肉面.md#step-3',262,3,NULL,'将220g 手擀面和3 颗青菜放入沸水中煮2 分钟；','主食/香辣牛肉面.md#step-3',120,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/香辣牛肉面.md#step-4',262,4,NULL,'舀取350g 的汤底于面碗中，放入煮好的面条；','主食/香辣牛肉面.md#step-4',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/香辣牛肉面.md#step-5',262,5,NULL,'将50g 牛肉、3 颗青菜、1 个卤蛋摆放于面条上，浇上150g牛肉汤，撒上10g 蒜花和5g 香菜末即可完成。','主食/香辣牛肉面.md#step-5',NULL,NULL,NULL,NULL);
