INSERT INTO dish_template_ingredients (template_id,ingredient_name,ingredient_category,quantity,unit,calc_type,source_text,source_quantity_text,quantity_status,component_template_id,source_line_key,component_occurrence_key,component_multiplier,sort_order) VALUES (264,'炒菜基料','调味料',NULL,NULL,NULL,'配料/炒菜基料.md','按来源配方','SOURCE_BATCH',505,'主食/香辣鸡丁拌面.md#component-1','主食/香辣鸡丁拌面.md#component-1',NULL,12);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/香辣鸡丁拌面.md#step-1',264,1,NULL,'香辣鸡丁炒制： ①200g 大豆油烧至180℃，加入700g 鸡丁炒熟； ②加入60g 拍蒜、100g 鲜红小米辣炒香； ③加入110g 炒菜基料翻炒均匀上色； ④加入400g 香干丁，煸炒1 分钟； ⑤加入200g 线椒圈，炒至断生，留待后续使用；','主食/香辣鸡丁拌面.md#step-1',60,'180℃',NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/香辣鸡丁拌面.md#step-2',264,2,NULL,'将275g 手擀面或130g 鲜面、25g 青菜在沸水中煮3 分钟；','主食/香辣鸡丁拌面.md#step-2',180,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/香辣鸡丁拌面.md#step-3',264,3,NULL,'面碗中加入15g 牛肉面汤底料、15g 拌菜红油、5g 蒜蓉、5g 熟猪油、15g 芝麻酱料，放入煮好的面条和青菜；','主食/香辣鸡丁拌面.md#step-3',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/香辣鸡丁拌面.md#step-4',264,4,NULL,'舀取125g 香辣鸡丁放于面条上，撒上5g 葱花即可完成。','主食/香辣鸡丁拌面.md#step-4',NULL,NULL,NULL,NULL);
