INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/鱼香肉丝盖饭（包菜版）.md#step-1',265,1,NULL,'鱼香肉丝炒制（10份）：(1) 180g大豆油烧至180℃，加入500g调理肉丝煸炒至肉丝变色；(2) 加入600g笋丝、300g胡萝卜丝、300g木耳丝翻炒均匀；(3) 加入300g鱼香风味酱翻炒2分钟，留待后续使用。','主食/鱼香肉丝盖饭（包菜版）.md#step-1',120,'180℃',NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/鱼香肉丝盖饭（包菜版）.md#step-2',265,2,NULL,'包菜烫制：取70g包菜，在沸水中烫1分钟，留待后续使用；','主食/鱼香肉丝盖饭（包菜版）.md#step-2',60,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/鱼香肉丝盖饭（包菜版）.md#step-3',265,3,NULL,'组合即可完成：餐盒中放入300g米饭，将1份鱼香肉丝、70g包菜、半个茶叶蛋放在米饭上，包菜上淋入10g豉油汁，即可完成。','主食/鱼香肉丝盖饭（包菜版）.md#step-3',NULL,NULL,NULL,NULL);
