INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/鱼香肉丝盖饭（菜苔版）.md#step-1',266,1,NULL,'鱼香肉丝炒制（10份）：(1) 180g大豆油烧至180℃，加入500g调理肉丝煸炒至肉丝变色；(2) 加入600g笋丝、300g胡萝卜丝、300g木耳丝翻炒均匀；(3) 加入300g鱼香风味酱翻炒2分钟，留待后续使用。','主食/鱼香肉丝盖饭（菜苔版）.md#step-1',120,'180℃',NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/鱼香肉丝盖饭（菜苔版）.md#step-2',266,2,NULL,'菜苔烫制：取70g菜苔，在沸水中烫1分钟，留待后续使用；','主食/鱼香肉丝盖饭（菜苔版）.md#step-2',60,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/鱼香肉丝盖饭（菜苔版）.md#step-3',266,3,NULL,'组合即可完成：餐盒中放入300g米饭，将1份鱼香肉丝、70g菜苔、半个茶叶蛋放在米饭上，菜苔上淋入15g豉油汁，即可完成。','主食/鱼香肉丝盖饭（菜苔版）.md#step-3',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_source_records (id,template_id,source_key,source_title,source_category,source_path,source_url,source_revision,record_type,alias_reason,content_sha256) VALUES (100050,266,'主食/鱼香肉丝盖饭（菜苔版）.md','鱼香肉丝盖饭（菜苔版）','主食','主食/鱼香肉丝盖饭（菜苔版）.md','https://cooklikehoc.soilzhu.su/主食/鱼香肉丝盖饭（菜苔版）','f7a91c2db0ce9b6a41eaf06e5ce64cbde5a831ed','PRIMARY',NULL,'acc3fee3d48e4726f3094d445f02a4cbd4111292ef42679430a8761c90f28a85');
