INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/鸡杂手擀面.md#step-1',267,1,NULL,'用盐揉搓鸡表皮，冷藏20分钟；每500g老母鸡，加入15g盐，28g调味料（鸡汤专用），50g鸡油，2500g水，烧开后炖制60分钟；','主食/鸡杂手擀面.md#step-1',1200,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/鸡杂手擀面.md#step-2',267,2,NULL,'水烧开，加入220g手擀面，煮熟；','主食/鸡杂手擀面.md#step-2',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('主食/鸡杂手擀面.md#step-3',267,3,NULL,'舀取300g老鸡汤，煮好的面条捞出沥水倒入碗中，将190g香辣鸡杂摆放上层，即可完成撒葱花。','主食/鸡杂手擀面.md#step-3',NULL,NULL,NULL,NULL);
