INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('凉拌/凉拌莴笋丝.md#step-3',268,3,NULL,'将腌制后的莴笋丝沥干水分，加入15g 红椒、30g 芝麻香油、10g 鸡精、5g 白砂糖，翻拌均匀即可完成。','凉拌/凉拌莴笋丝.md#step-3',NULL,NULL,NULL,NULL);
