INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('早餐/蔬菜鸡蛋卷饼.md#step-1',299,1,NULL,'炒合菜（3 份）：(1) 加入 40g 大豆油、125g 混合鸡蛋液（125g 蛋液+0.5g 盐），炒制蛋片，出锅；(2) 加入大豆油 20g，加入包菜丝 150g、胡萝卜丝 50g、盐 1g、鸡精 4g、蚝油 6g、生抽 15g；(3) 加入 83g 粉丝（80g 泡发粉丝+3g 老抽），最后加入鸡蛋块，炒制约 30 秒；加入葱花，翻搅均匀关火。','早餐/蔬菜鸡蛋卷饼.md#step-1',30,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('早餐/蔬菜鸡蛋卷饼.md#step-2',299,2,NULL,'卷制：蒸制好的饼皮放入 100g 炒合菜，卷制成型。','早餐/蔬菜鸡蛋卷饼.md#step-2',NULL,NULL,NULL,NULL);
