INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('早餐/鸡丝沙汤.md#step-1',310,1,NULL,'称取5000g水，烧开加入375g木耳碎、120g鸡丝、60g沙汤调味粉、100g沙汤骨汤料、6g黑胡椒粉，再次烧开；淋入淀粉水（200g淀粉+250g水），继续大火烧开；','早餐/鸡丝沙汤.md#step-1',NULL,NULL,'大火',NULL);
