INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('汤/金牌老母鸡汤.md#step-4',317,4,NULL,'剁好的鸡块放入汤中，加入35g盐炖煮15分钟；即可完成前捞去浮沫。','汤/金牌老母鸡汤.md#step-4',900,NULL,NULL,NULL);
