INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/小炒河虾.md#step-1',326,1,NULL,'锅中倒入120g 大豆油烧至160℃，将500g 蛋液炒制成鸡蛋丁状，盛出锅留待后续使用；','炒菜/小炒河虾.md#step-1',NULL,'160℃',NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/小炒河虾.md#step-2',326,2,NULL,'再次倒入120g 大豆油，加入100g 蒜子、50g 鲜红小米辣；','炒菜/小炒河虾.md#step-2',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/小炒河虾.md#step-3',326,3,NULL,'爆香后加入800g 青椒丁煸炒30 秒，撒入14g 盐翻炒；','炒菜/小炒河虾.md#step-3',30,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/小炒河虾.md#step-4',326,4,NULL,'加入500g 河虾、70g 小炒河虾料、鸡蛋丁均匀翻炒1 分钟即可完成','炒菜/小炒河虾.md#step-4',60,NULL,NULL,NULL);
