INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/毛豆烧土鸡.md#step-1',333,1,NULL,'锅中混合 130g 菜籽油和 40g 熟猪油，烧至油温 180℃；','炒菜/毛豆烧土鸡.md#step-1',NULL,'180℃',NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/毛豆烧土鸡.md#step-2',333,2,NULL,'倒入 1500g 鸡块，煸炒至鸡肉表面泛黄；','炒菜/毛豆烧土鸡.md#step-2',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/毛豆烧土鸡.md#step-3',333,3,NULL,'鸡肉中加入 60g 蒜子、60g 姜片、50g 剁椒翻炒;','炒菜/毛豆烧土鸡.md#step-3',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/毛豆烧土鸡.md#step-4',333,4,NULL,'炒香后放入 150g 毛豆烧鸡料炒至鸡块上色；','炒菜/毛豆烧土鸡.md#step-4',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/毛豆烧土鸡.md#step-5',333,5,NULL,'加入 120g 皮冻、280g 水一起烧开；','炒菜/毛豆烧土鸡.md#step-5',NULL,NULL,NULL,NULL);
