INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/笋子鸡丁盖饭.md#step-1',344,1,'剁椒鸡丁炒制：','180g 大豆油烧至 180℃、加入 700g 鸡丁炒熟；','炒菜/笋子鸡丁盖饭.md#step-1',NULL,'180℃',NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/笋子鸡丁盖饭.md#step-2',344,2,'剁椒鸡丁炒制：','加入 8g 老抽、5g 鸡精、2g 盐，将鸡丁炒制上色；','炒菜/笋子鸡丁盖饭.md#step-2',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/笋子鸡丁盖饭.md#step-3',344,3,'剁椒鸡丁炒制：','加入 120g 剁椒酱、300g 焯水罗汉笋块，一起炒香；','炒菜/笋子鸡丁盖饭.md#step-3',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/笋子鸡丁盖饭.md#step-4',344,4,'剁椒鸡丁炒制：','加入 36g 蒜花翻炒均匀，留待后续使用；','炒菜/笋子鸡丁盖饭.md#step-4',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/笋子鸡丁盖饭.md#step-5',344,5,'菜苔烫制','取 70g 菜苔，在沸水中烫 1 分钟，留待后续使用；','炒菜/笋子鸡丁盖饭.md#step-5',60,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/笋子鸡丁盖饭.md#step-6',344,6,'装配','餐盒中放入 300g 米饭，将 170g 剁椒鸡丁、70g 菜苔、半个卤蛋放在米饭上，菜苔上淋入 15g 豉油汁即可完成。','炒菜/笋子鸡丁盖饭.md#step-6',NULL,NULL,NULL,NULL);
