INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/经典毛豆烧鸡.md#step-1',345,1,NULL,'锅中混合90g菜籽油和40g熟猪油，烧至180℃；','炒菜/经典毛豆烧鸡.md#step-1',NULL,'180℃',NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/经典毛豆烧鸡.md#step-2',345,2,NULL,'倒入1700g鸡块，煸炒至鸡块表面泛黄出油；','炒菜/经典毛豆烧鸡.md#step-2',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/经典毛豆烧鸡.md#step-3',345,3,NULL,'加入60g姜片、60g拍蒜、50g剁椒，炒出香味；','炒菜/经典毛豆烧鸡.md#step-3',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/经典毛豆烧鸡.md#step-4',345,4,NULL,'加入毛豆烧鸡料快速翻炒使鸡块上色入味；','炒菜/经典毛豆烧鸡.md#step-4',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/经典毛豆烧鸡.md#step-5',345,5,NULL,'加入水和120g皮冻烧开；','炒菜/经典毛豆烧鸡.md#step-5',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/经典毛豆烧鸡.md#step-6',345,6,NULL,'加入750g豆米，大火收汁，出锅前加入30g葱段翻拌均匀。','炒菜/经典毛豆烧鸡.md#step-6',NULL,NULL,'大火',NULL);
