INSERT INTO dish_template_ingredients (template_id,ingredient_name,ingredient_category,quantity,unit,calc_type,source_text,source_quantity_text,quantity_status,component_template_id,source_line_key,component_occurrence_key,component_multiplier,sort_order) VALUES (346,'肥肠鸡酱料','调味料',NULL,NULL,NULL,'配料/肥肠鸡酱料.md','按来源配方','SOURCE_BATCH',510,'炒菜/肥肠鸡.md#component-1','炒菜/肥肠鸡.md#component-1',NULL,16);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/肥肠鸡.md#step-1',346,1,'鸡块制作：','加入 350g 菜籽油、200g 猪油、清洗好沥干水分的 3200g 鸡块，煸炒至表皮微黄；','炒菜/肥肠鸡.md#step-1',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/肥肠鸡.md#step-2',346,2,'鸡块制作：','加入 50g 葱、140g 姜、200g 蒜，炒出香味；','炒菜/肥肠鸡.md#step-2',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/肥肠鸡.md#step-3',346,3,'鸡块制作：','加入 800g 肥肠鸡酱料，翻炒均匀；','炒菜/肥肠鸡.md#step-3',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/肥肠鸡.md#step-4',346,4,'鸡块制作：','加入 3000g 水、40g 盐，煮制 2 分钟即可倒出，鸡块和汤留待后续使用。','炒菜/肥肠鸡.md#step-4',120,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/肥肠鸡.md#step-5',346,5,'配菜制作：','锅中加入适量的水和盐，烧开后倒入蔬菜；','炒菜/肥肠鸡.md#step-5',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/肥肠鸡.md#step-6',346,6,'配菜制作：','再次烧开后煮制 1 分钟，捞出冲凉留待后续使用。','炒菜/肥肠鸡.md#step-6',60,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/肥肠鸡.md#step-7',346,7,'肥肠鸡制作：','将泡发好的 50g 宽粉和焯水后的 60g 土豆片、80g 莴笋片烫制20 秒，沥干水分放入盘中；','炒菜/肥肠鸡.md#step-7',20,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/肥肠鸡.md#step-8',346,8,'肥肠鸡制作：','锅中放入 200g 煮制鸡块、80g 肥肠、70g 芋艿、250g 汤、50g泡菜，煮制 3 分钟；','炒菜/肥肠鸡.md#step-8',180,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/肥肠鸡.md#step-9',346,9,'肥肠鸡制作：','再加入 8g 线椒、5g 鲜红小米辣、10g 芝麻香油、5g 花椒油，继续煮制 1 分钟，关火倒入盘中；','炒菜/肥肠鸡.md#step-9',60,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/肥肠鸡.md#step-10',346,10,'肥肠鸡制作：','向 20g 热大豆油加入 2g 干青花椒、5g 干红辣椒段，炸出糊辣味后均匀淋到菜上；','炒菜/肥肠鸡.md#step-10',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/肥肠鸡.md#step-11',346,11,'肥肠鸡制作：','最后点缀 5g 白芝麻、5g 香菜段，即可即可完成。','炒菜/肥肠鸡.md#step-11',NULL,NULL,NULL,NULL);
