INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/胡萝卜炒鸡蛋.md#step-1',350,1,NULL,'加入 200g 大豆油、600g 鸡蛋液，炒成鸡蛋片，出锅留待后续使用；','炒菜/胡萝卜炒鸡蛋.md#step-1',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/胡萝卜炒鸡蛋.md#step-2',350,2,NULL,'加入 100g 大豆油、1500g 胡萝卜丝、14g 盐、14g 鸡精，炒制 2 分钟；','炒菜/胡萝卜炒鸡蛋.md#step-2',120,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/胡萝卜炒鸡蛋.md#step-3',350,3,NULL,'最后加入鸡蛋片，大火爆炒 1 分 40 秒，最后加入 30g 葱段，翻炒均匀即可完成。','炒菜/胡萝卜炒鸡蛋.md#step-3',100,NULL,'大火',NULL);
