INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/菠萝咕咾肉时蔬饭.md#step-1',355,1,NULL,'炒饭： 加入80g 大豆油，将150g 鸡蛋液炒成鸡蛋片状；再倒 入1000g 冷藏米饭，翻炒3 分钟至米饭呈松散状态，最 后加入10g 老抽、3g 盐继续翻炒1 分钟。','炒菜/菠萝咕咾肉时蔬饭.md#step-1',180,NULL,NULL,NULL);
