INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/鱼香肉丝盖饭.md#step-1',377,1,'鱼香肉丝炒制：','180g 大豆油烧至 180℃，加入 500g 调理肉丝煸炒至肉丝变色；','炒菜/鱼香肉丝盖饭.md#step-1',NULL,'180℃',NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/鱼香肉丝盖饭.md#step-2',377,2,'鱼香肉丝炒制：','加入 600g 笋丝、300g 胡萝卜丝、300g 木耳丝翻炒均匀','炒菜/鱼香肉丝盖饭.md#step-2',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/鱼香肉丝盖饭.md#step-3',377,3,'鱼香肉丝炒制：','加入 300g 鱼香风味酱翻炒 2 分钟即可完成吗，留待后续使用。','炒菜/鱼香肉丝盖饭.md#step-3',120,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/鱼香肉丝盖饭.md#step-4',377,4,'菜苔烫制：','取 70g 菜苔，在沸水中烫 1 分钟，留待后续使用；','炒菜/鱼香肉丝盖饭.md#step-4',60,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('炒菜/鱼香肉丝盖饭.md#step-5',377,5,'装配：','餐盒中放入 300g 米饭，将 1 份鱼香肉丝、70g 菜苔、半个卤蛋放在米饭，菜苔上淋入 15g 豉油汁，即可完成。','炒菜/鱼香肉丝盖饭.md#step-5',NULL,NULL,NULL,NULL);
