INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('烫菜/麻辣鸡块.md#step-1',419,1,NULL,'老母鸡炖制：每只老母鸡加入 2g 盐，冷藏腌制 20 分钟；每 500g 老母鸡，加入 16g 盐、60g 鸡油、2500g 水，炖煮出老母鸡汤香味，老母鸡剁块留待后续使用；','烫菜/麻辣鸡块.md#step-1',1200,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('烫菜/麻辣鸡块.md#step-2',419,2,NULL,'1 份麻辣鸡块调味汁配制：味极鲜酱油 25g、麻辣油 15g、直饮水 15g、红椒丁 10g、京葱丁 5g;','烫菜/麻辣鸡块.md#step-2',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('烫菜/麻辣鸡块.md#step-3',419,3,NULL,'将老鸡块放入沸水中烫 2 分钟，捞起沥干水分，淋上70g 调味汁即可完成。','烫菜/麻辣鸡块.md#step-3',120,NULL,NULL,NULL);
