INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('煮锅/冒烤鸭.md#step-1',420,1,NULL,'底汤调配： 500g 冒烤鸭底料、2500g 白开水，搅拌融化后，熬煮 3 分钟留待后续使用；','煮锅/冒烤鸭.md#step-1',180,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('煮锅/冒烤鸭.md#step-2',420,2,NULL,'取 50g 绿豆芽、50g 千张丝加入沸水中汆烫 2 分钟，沥水后倒入餐具中，再加入 20g 蒜末和 30g 冒菜红油；','煮锅/冒烤鸭.md#step-2',120,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('煮锅/冒烤鸭.md#step-3',420,3,NULL,'锅中倒入 300g 底汤、300g 烤鸭块，煮 4 分钟后，倒在绿豆芽和千张丝上，即可完成撒 3g 白芝麻、2g 葱花和 2g 香菜点缀。','煮锅/冒烤鸭.md#step-3',240,NULL,NULL,NULL);
