INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('煮锅/嗨嗨锅（泡椒鸡米花米线）.md#step-1',421,1,NULL,'10 份泡椒骨汤汤底调制：2900g 开水中加入140g 骨汤调味料、700g 泡椒调味料，搅拌均匀留待后续使用；','煮锅/嗨嗨锅（泡椒鸡米花米线）.md#step-1',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('煮锅/嗨嗨锅（泡椒鸡米花米线）.md#step-2',421,2,NULL,'奶锅中加入370g 泡椒骨汤汤底烧开；','煮锅/嗨嗨锅（泡椒鸡米花米线）.md#step-2',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('煮锅/嗨嗨锅（泡椒鸡米花米线）.md#step-3',421,3,NULL,'加入50g 西红柿片、50g 娃娃菜、20g 木耳丝，20g 海带丝烧开后煮2 分钟，倒入红底座锅中；','煮锅/嗨嗨锅（泡椒鸡米花米线）.md#step-3',120,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('煮锅/嗨嗨锅（泡椒鸡米花米线）.md#step-4',421,4,NULL,'将250g 湿米线在沸水中煮2 分30 秒后，倒入红底座锅中，放入60g 炸制好的鸡米花即可完成。','煮锅/嗨嗨锅（泡椒鸡米花米线）.md#step-4',150,NULL,NULL,NULL);
