INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('煮锅/金汤酸菜鱼（大份）.md#step-1',426,1,NULL,'底汤调配（5 份）： 2480g 白开水、350g 金汤，搅拌均匀留待后续使用；','煮锅/金汤酸菜鱼（大份）.md#step-1',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('煮锅/金汤酸菜鱼（大份）.md#step-2',426,2,NULL,'80g 娃娃菜和泡发好的 85g 粉丝加入沸水中汆烫 10 秒，捞起沥水后倒入装有 80g 小叶酸菜的餐具中，再将 150g 黑鱼片加入沸水中汆烫 30 秒，捞起沥水后平铺在娃娃菜、玉耳上，倒入 500g 底汤；','煮锅/金汤酸菜鱼（大份）.md#step-2',10,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('煮锅/金汤酸菜鱼（大份）.md#step-3',426,3,NULL,'锅中倒入 20g 大豆油烧至 120℃，关火后加入 5g 干红椒、2g 干青花椒、5g 蒜末爆香 2 秒，倒入黑鱼片上，即可完成撒1g 芝麻和 1g 葱花点缀。','煮锅/金汤酸菜鱼（大份）.md#step-3',2,'120℃',NULL,NULL);
