INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('煮锅/铜锅安格斯肥牛.md#step-2',427,2,NULL,'安格斯肥牛煮制：(1) 奶锅中加入30g大豆油，烧至160℃; (2) 加入60g洋葱丝，炒至微黄; (3) 加入130g照烧肥牛汁、70g金针菇烧开; (4) 加入100g肥牛片煮至肥牛片完全熟透，倒入铜锅中即可完成。','煮锅/铜锅安格斯肥牛.md#step-2',NULL,'160℃',NULL,NULL);
