INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('煮锅/铜锅川味水煮肉片.md#step-2',428,2,NULL,'铜锅川味水煮肉片煮制：(1) 奶锅中入300g汤底（需搅拌均匀）5档烧开；(2) 加入50g娃娃菜、50g莴笋片和30g木耳，煮制入味；(3) 加入100g调理肉片煮至变色，加入2g干红椒、5g蒜末，淋入10g烧至120℃的大豆油爆香，最后撒入1g葱花即可完成。','煮锅/铜锅川味水煮肉片.md#step-2',NULL,'120℃',NULL,NULL);
