INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('砂锅菜/砂锅肉汁素鸡.md#step-1',439,1,NULL,'炒螺丝椒片：锅中加入30g菜籽油烧至160℃，加入200g螺丝椒片炒制约30秒，倒入份盒留待后续使用；','砂锅菜/砂锅肉汁素鸡.md#step-1',30,'160℃',NULL,NULL);
