INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('砂锅菜/砂锅肉汁素鸡.md#step-3',439,3,NULL,'砂锅煲制（单份即可完成）：砂锅中加入270g固形物、150g汤汁，加入20g炒螺丝椒片，加盖烧开后煮约2分钟即可完成。','砂锅菜/砂锅肉汁素鸡.md#step-3',120,NULL,NULL,NULL);
