INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('砂锅菜/砂锅豆花鸡.md#step-1',442,1,NULL,'炒线椒：锅中水分烧干，加入50g大豆油烧至160℃，加入300g线椒圈炒制约10秒，留待后续使用；','砂锅菜/砂锅豆花鸡.md#step-1',10,'160℃',NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('砂锅菜/砂锅豆花鸡.md#step-2',442,2,NULL,'鸡块炒制：锅中加入80g菜籽油、40g熟猪油烧至180℃，加入1700g鸡块，炒至鸡块表面泛黄出油；加入60g姜片、60g蒜子，炒香，加入水、350g酱料烧煮；','砂锅菜/砂锅豆花鸡.md#step-2',NULL,'180℃',NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('砂锅菜/砂锅豆花鸡.md#step-3',442,3,NULL,'砂锅煲制（单份即可完成）：砂锅中加入150g豆花豆腐、100g熟鸡块、120g汤汁加盖烧开后转小火煮约2分钟，加入30g炒线椒，即可完成。','砂锅菜/砂锅豆花鸡.md#step-3',120,NULL,'小火',NULL);
