INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('砂锅菜/砂锅香辣鱿鱼.md#step-1',444,1,NULL,'鱿鱼炒制：锅中加入100g大豆油烧至160℃，加入30g姜片、60g拍蒜、10g鲜红小米辣段，炒至爆香；加入1100g鱿鱼条、800g焯水后的土豆条翻炒均匀；加入400g香辣爆炒酱，翻炒均匀，之后再加入50g水，炒香；','砂锅菜/砂锅香辣鱿鱼.md#step-1',NULL,'160℃',NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('砂锅菜/砂锅香辣鱿鱼.md#step-2',444,2,NULL,'砂锅煲制（单份即可完成）：砂锅中加入10g大豆油、60g洋葱丝、210g鱿鱼，加盖烧开，撒入1g葱花即可完成。','砂锅菜/砂锅香辣鱿鱼.md#step-2',NULL,NULL,NULL,NULL);
