INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('砂锅菜/酸菜肥肠煲.md#step-6',445,6,'装配：','将 80g 小叶酸菜平铺在砂锅底部，放入 230g 烧制后的肥肠，烧开后煮 1 分钟，撒 10g 蒜花即可完成。','砂锅菜/酸菜肥肠煲.md#step-6',60,NULL,NULL,NULL);
