INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('蒸菜/肉饼蒸蛋.md#step-1',462,1,NULL,'肉饼蒸蛋汁调配（9 份）：180g 老鸡汤、20g 生抽，搅拌均匀；','蒸菜/肉饼蒸蛋.md#step-1',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('蒸菜/肉饼蒸蛋.md#step-2',462,2,NULL,'肉馅调配（9 份）：取 1000g 调理肉丝剁碎，加入 10g 鸡精和 100g 水，搅拌上劲后再加 100g 水，再次搅拌上劲，加入 20g 淀粉，搅拌均匀；','蒸菜/肉饼蒸蛋.md#step-2',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('蒸菜/肉饼蒸蛋.md#step-3',462,3,NULL,'肉饼蒸蛋操作（1份）：在餐具中放130g肉馅，用汤勺将肉馅中心部按压出凹陷小窝，并打入一颗鸡蛋；','蒸菜/肉饼蒸蛋.md#step-3',NULL,NULL,NULL,NULL);
