INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('蒸菜/葱油鸡（小母鸡版）.md#step-1',466,1,NULL,'葱油鸡调料配制（1份）：27g味极鲜酱油、7g葱油、17g纯净水；','蒸菜/葱油鸡（小母鸡版）.md#step-1',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('蒸菜/葱油鸡（小母鸡版）.md#step-2',466,2,NULL,'每500g鸡用5g盐、3g鸡精、3g葱段、3g姜片腌制20分钟；','蒸菜/葱油鸡（小母鸡版）.md#step-2',1200,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('蒸菜/葱油鸡（小母鸡版）.md#step-3',466,3,NULL,'腌制好的小母鸡放入蒸柜中蒸制20-35分钟，将蒸制后的小母鸡取出，分切为宽度1.5-2厘米，长度6-8cm的块状，每份鸡块标准重量为190g；','蒸菜/葱油鸡（小母鸡版）.md#step-3',2100,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('蒸菜/葱油鸡（小母鸡版）.md#step-4',466,4,NULL,'菜品即可完成之前放入蒸柜蒸制3分钟，即可完成时淋入50g葱油鸡调料，撒上1g葱花点缀。','蒸菜/葱油鸡（小母鸡版）.md#step-4',180,NULL,NULL,NULL);
