INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('蒸菜/香辣红油鸡（白切鸡版）.md#step-1',486,1,NULL,'香辣红油蘸料1包，添加20g陈醋、50g生抽、30g蒜末，充分搅拌均匀后留待后续使用；','蒸菜/香辣红油鸡（白切鸡版）.md#step-1',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('蒸菜/香辣红油鸡（白切鸡版）.md#step-2',486,2,NULL,'将鸡腿、鸡翅、鸡身切分为宽度1.5-2cm、长度6-8cm的块状，鸡脖、鸡爪分切为宽度约1.5cm的块状，每份鸡块标准重量为190g；','蒸菜/香辣红油鸡（白切鸡版）.md#step-2',NULL,NULL,NULL,NULL);
INSERT INTO dish_template_cooking_steps (item_key,template_id,step_no,title,content,source_text,duration_seconds,temperature_text,heat_level,component_template_id) VALUES ('蒸菜/香辣红油鸡（白切鸡版）.md#step-3',486,3,NULL,'取190g切好的白切鸡块放入餐具中，即可完成之前放入蒸柜蒸制3分钟，即可完成时淋入40g调配好的蘸料，撒上1g葱花点缀。','蒸菜/香辣红油鸡（白切鸡版）.md#step-3',180,NULL,NULL,NULL);
