-- 将完整 CookLikeHOC 菜谱同步到已执行旧版 V4/V5/V6 的现有数据库。
-- 所有关联 ID 均由应用层校验，不创建物理外键。

ALTER TABLE dish_templates
  MODIFY COLUMN description varchar(255) NULL COMMENT '模板菜品简介',
  MODIFY COLUMN image_url varchar(500) NULL COMMENT '审核发布后的本地图片访问地址',
  MODIFY COLUMN image_source_url varchar(1000) NULL COMMENT '已声明授权图片的来源页面',
  MODIFY COLUMN image_author varchar(255) NULL COMMENT '已声明授权图片的作者或来源平台',
  MODIFY COLUMN image_license varchar(255) NULL COMMENT '已声明授权图片的许可证',
  MODIFY COLUMN reference_price decimal(10,2) NULL COMMENT '家庭私厨参考价',
  ADD COLUMN template_type varchar(20) NOT NULL DEFAULT 'DISH' COMMENT '模板类型：DISH成品菜、COMPONENT配料组件' AFTER meal_tags,
  ADD COLUMN source_type varchar(30) NOT NULL DEFAULT 'LOCAL_EXTENSION' COMMENT '来源类型：COOK_LIKE_HOC、LOCAL_EXTENSION' AFTER template_type,
  ADD COLUMN source_key varchar(500) NULL COMMENT '主来源文件的稳定规范化键' AFTER source_type,
  ADD COLUMN source_url varchar(1000) NULL COMMENT '来源菜谱页面地址' AFTER source_key,
  ADD COLUMN source_revision varchar(64) NULL COMMENT '来源仓库固定提交版本' AFTER source_url,
  ADD COLUMN source_category varchar(100) NULL COMMENT '来源仓库原始分类' AFTER source_revision,
  ADD COLUMN source_yield_text varchar(255) NULL COMMENT '来源份数或批次说明原文' AFTER source_category,
  ADD COLUMN data_status varchar(30) NOT NULL DEFAULT 'READY' COMMENT '数据状态：READY、NEEDS_PURCHASE_DATA、NEEDS_PRICE、NEEDS_BOTH' AFTER source_yield_text,
  ADD COLUMN procurement_ready tinyint(1) NOT NULL DEFAULT 1 COMMENT '采购用量是否完成家庭化校验' AFTER data_status,
  ADD COLUMN image_rights_status varchar(20) NOT NULL DEFAULT 'DECLARED' COMMENT '图片权利状态：DECLARED、UNDECLARED、NONE' AFTER procurement_ready,
  ADD CONSTRAINT chk_dish_template_type CHECK (template_type IN ('DISH','COMPONENT')),
  ADD CONSTRAINT chk_dish_template_source_type CHECK (source_type IN ('COOK_LIKE_HOC','LOCAL_EXTENSION')),
  ADD CONSTRAINT chk_dish_template_data_status CHECK (data_status IN ('READY','NEEDS_PURCHASE_DATA','NEEDS_PRICE','NEEDS_BOTH')),
  ADD CONSTRAINT chk_template_image_rights CHECK ((image_rights_status IN ('UNDECLARED','NONE') AND image_url IS NULL) OR (image_rights_status='DECLARED' AND image_url IS NOT NULL AND image_source_url IS NOT NULL AND image_author IS NOT NULL AND image_license IS NOT NULL)),
  ADD UNIQUE KEY uk_dish_templates_source_key (source_key),
  ADD KEY idx_dish_templates_market (template_type,data_status,procurement_ready,enabled);

ALTER TABLE dish_template_ingredients
  MODIFY COLUMN ingredient_name varchar(255) NOT NULL COMMENT '食材名称',
  MODIFY COLUMN quantity decimal(10,2) NULL COMMENT '经家庭化校验的采购数量',
  MODIFY COLUMN unit varchar(20) NULL COMMENT '经家庭化校验的计量单位',
  MODIFY COLUMN calc_type varchar(20) NULL COMMENT '计算方式：FIXED、PER_PERSON',
  ADD COLUMN source_text varchar(1000) NULL COMMENT '归一化后的来源原料行' AFTER calc_type,
  ADD COLUMN source_quantity_text varchar(255) NULL COMMENT '来源批量用量原文' AFTER source_text,
  ADD COLUMN quantity_status varchar(30) NOT NULL DEFAULT 'VERIFIED' COMMENT '数量状态：VERIFIED、SOURCE_BATCH、MISSING、NOT_APPLICABLE' AFTER source_quantity_text,
  ADD COLUMN component_template_id bigint NULL COMMENT '引用配料组件模板的逻辑ID' AFTER quantity_status,
  ADD COLUMN source_line_key varchar(500) NULL COMMENT '来源文件和原料行组成的稳定键' AFTER component_template_id,
  ADD COLUMN component_occurrence_key varchar(500) NULL COMMENT '组件在当前菜谱中的引用出现键' AFTER source_line_key,
  ADD COLUMN component_multiplier decimal(12,4) NULL COMMENT '经验证的组件引用倍数' AFTER component_occurrence_key,
  ADD CONSTRAINT chk_template_ingredient_quantity_state CHECK ((quantity_status='VERIFIED' AND quantity>0 AND unit IS NOT NULL AND CHAR_LENGTH(TRIM(unit))>0 AND calc_type IN ('FIXED','PER_PERSON')) OR (quantity_status IN ('SOURCE_BATCH','MISSING') AND quantity IS NULL AND unit IS NULL AND calc_type IS NULL) OR (quantity_status='NOT_APPLICABLE' AND quantity IS NULL AND unit IS NULL AND calc_type IS NULL)),
  ADD UNIQUE KEY uk_dish_template_ingredients_source_line (source_line_key);

CREATE TABLE dish_template_source_records (
  id bigint PRIMARY KEY AUTO_INCREMENT COMMENT '模板来源记录ID',
  template_id bigint NOT NULL COMMENT '平台菜品模板逻辑ID',
  source_key varchar(500) NOT NULL COMMENT '来源文件稳定规范化键',
  source_title varchar(255) NOT NULL COMMENT '来源菜谱标题',
  source_category varchar(100) NOT NULL COMMENT '来源仓库原始分类',
  source_path varchar(1000) NOT NULL COMMENT '来源仓库相对路径',
  source_url varchar(1000) NOT NULL COMMENT '来源菜谱页面地址',
  source_revision varchar(64) NOT NULL COMMENT '来源仓库固定提交版本',
  record_type varchar(30) NOT NULL COMMENT '记录类型：PRIMARY、SOURCE_ALIAS、PATH_RENAME',
  alias_reason varchar(500) NULL COMMENT '来源别名或路径重命名原因',
  content_sha256 char(64) NOT NULL COMMENT '规范化Markdown内容SHA-256',
  created_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  CONSTRAINT chk_dish_template_source_record_type CHECK (record_type IN ('PRIMARY','SOURCE_ALIAS','PATH_RENAME')),
  UNIQUE KEY uk_dish_template_source_records_key (source_key),
  KEY idx_dish_template_source_records_template (template_id,record_type,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='平台菜品模板来源记录表';

CREATE TABLE dish_template_name_aliases (
  id bigint PRIMARY KEY AUTO_INCREMENT COMMENT '模板名称别名ID',
  template_id bigint NOT NULL COMMENT '平台菜品模板逻辑ID',
  alias_name varchar(255) NOT NULL COMMENT '模板名称别名',
  normalized_alias_name varchar(255) NOT NULL COMMENT '规范化后的全局唯一别名',
  alias_type varchar(30) NOT NULL COMMENT '别名类型：LOCAL_PREVIOUS_NAME、SOURCE_TITLE_VARIANT、MANUAL',
  created_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  CONSTRAINT chk_dish_template_name_alias_type CHECK (alias_type IN ('LOCAL_PREVIOUS_NAME','SOURCE_TITLE_VARIANT','MANUAL')),
  UNIQUE KEY uk_dish_template_name_aliases_normalized (normalized_alias_name),
  KEY idx_dish_template_name_aliases_template (template_id,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='平台菜品模板名称别名表';

CREATE TABLE dish_template_cooking_steps (
  id bigint PRIMARY KEY AUTO_INCREMENT COMMENT '模板制作步骤ID',
  item_key varchar(500) NULL COMMENT '跨完整快照保持稳定的步骤项键',
  template_id bigint NOT NULL COMMENT '平台菜品模板逻辑ID',
  step_no int NOT NULL COMMENT '步骤序号',
  title varchar(100) NULL COMMENT '步骤标题',
  content text NOT NULL COMMENT '归纳后的完整制作操作',
  source_text varchar(1000) NULL COMMENT '简短来源定位和事实摘要',
  duration_seconds int NULL COMMENT '可可靠识别的持续秒数',
  temperature_text varchar(100) NULL COMMENT '可可靠识别的温度说明',
  heat_level varchar(50) NULL COMMENT '可可靠识别的火候说明',
  component_template_id bigint NULL COMMENT '当前步骤使用的配料组件逻辑ID',
  UNIQUE KEY uk_dish_template_cooking_steps_item_key (item_key),
  UNIQUE KEY uk_dish_template_cooking_steps_template_step (template_id,step_no),
  KEY idx_dish_template_cooking_steps_component (component_template_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='平台菜品模板制作步骤表';

CREATE TABLE dish_template_image_assets (
  id bigint PRIMARY KEY AUTO_INCREMENT COMMENT '模板内部图片资产ID',
  template_id bigint NOT NULL COMMENT '平台菜品模板逻辑ID',
  source_record_id bigint NOT NULL COMMENT '模板来源记录逻辑ID',
  internal_storage_key varchar(500) NOT NULL COMMENT '服务端内部私有存储键',
  content_sha256 char(64) NOT NULL COMMENT '图片内容SHA-256',
  mime_type varchar(100) NOT NULL COMMENT '图片MIME类型',
  file_size bigint NOT NULL COMMENT '图片字节数',
  source_image_path varchar(1000) NOT NULL COMMENT '来源仓库图片相对路径',
  source_url varchar(1000) NOT NULL COMMENT '来源菜谱页面地址',
  source_revision varchar(64) NOT NULL COMMENT '来源仓库固定提交版本',
  asset_status varchar(30) NOT NULL DEFAULT 'INTERNAL_REVIEW' COMMENT '资产状态：INTERNAL_REVIEW、PUBLISHED、REJECTED',
  public_image_url varchar(500) NULL COMMENT '审核发布后的公共图片地址',
  image_author varchar(255) NULL COMMENT '审核确认的图片作者',
  image_license varchar(255) NULL COMMENT '审核确认的图片许可证',
  reviewed_by bigint NULL COMMENT '审核平台管理员用户ID',
  reviewed_at datetime NULL COMMENT '审核时间',
  rejection_reason varchar(500) NULL COMMENT '拒绝原因',
  created_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  updated_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  CONSTRAINT chk_dish_template_image_asset_status CHECK (asset_status IN ('INTERNAL_REVIEW','PUBLISHED','REJECTED')),
  CONSTRAINT chk_template_image_asset_rejection CHECK ((asset_status='REJECTED' AND rejection_reason IS NOT NULL AND CHAR_LENGTH(TRIM(rejection_reason))>0) OR (asset_status<>'REJECTED' AND rejection_reason IS NULL)),
  UNIQUE KEY uk_dish_template_image_assets_source (template_id,source_revision,source_image_path(512),content_sha256),
  UNIQUE KEY uk_dish_template_image_assets_storage (internal_storage_key),
  KEY idx_dish_template_image_assets_status (asset_status,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='平台菜品模板内部图片审核资产表';

ALTER TABLE dish_cooking_steps
  ADD COLUMN duration_seconds int NULL COMMENT '制作持续秒数' AFTER content,
  ADD COLUMN temperature_text varchar(100) NULL COMMENT '制作温度说明' AFTER duration_seconds,
  ADD COLUMN heat_level varchar(50) NULL COMMENT '制作火候说明' AFTER temperature_text,
  ADD COLUMN source_template_step_id bigint NULL COMMENT '来源平台模板步骤逻辑ID' AFTER heat_level,
  ADD COLUMN component_template_id bigint NULL COMMENT '来源配料组件模板逻辑ID' AFTER source_template_step_id,
  ADD COLUMN source_note varchar(1000) NULL COMMENT '来源步骤简短追踪说明' AFTER component_template_id;

ALTER TABLE dish_ingredients
  MODIFY COLUMN ingredient_name varchar(255) NOT NULL COMMENT '食材名称';

ALTER TABLE purchase_list_items
  MODIFY COLUMN ingredient_name varchar(255) NOT NULL COMMENT '采购食材名称';

ALTER TABLE temp_purchase_items
  MODIFY COLUMN ingredient_name varchar(255) NOT NULL COMMENT '临时采购食材名称';

